INSERT INTO fleet_adr_repository_files (id, adr_id, ordinal, repository_origin, path, commit_sha, created_at, updated_at) VALUES (?1,?2,CAST(?3 AS INTEGER),?4,?5,?6,CAST(?7 AS INTEGER),CAST(?7 AS INTEGER)) ON CONFLICT(adr_id,ordinal) DO UPDATE SET repository_origin=excluded.repository_origin,path=excluded.path,commit_sha=excluded.commit_sha,updated_at=excluded.updated_at WHERE repository_origin IS NOT excluded.repository_origin OR path IS NOT excluded.path OR commit_sha IS NOT excluded.commit_sha;
